    return workbook["99_调节草稿"]


def _norm(value):
    if value is None:
        return ""
    return re.sub(r"[\s，。；：、（）()\-_/]+", "", str(value)).lower()


def _number(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _rows(ws):
    ws = _coerce_sheet(ws)
    for row in ws.iter_rows(min_row=6, values_only=True):
        values = list(row[:8])
        if any(value not in (None, "") for value in values):
            yield values


